import{_ as i,o as t,c as a,a3 as r}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Automatic Production Balancing Explanation: Script","description":"","frontmatter":{"translationSource":{"title":"自动配平讲解 脚本","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=QRCRN4XRWoQFThOwgWYo8s","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/automatic-production-balancing-explanation-script"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/automatic-production-balancing-explanation-script"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/automatic-production-balancing-explanation-script"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/automatic-production-balancing-explanation-script"}]]},"headers":[],"relativePath":"automatic-production-balancing-explanation-script.md","filePath":"logistics/src/page-QRCRN4XRWoQFThOwgWYo8s.md"}'),n={name:"automatic-production-balancing-explanation-script.md"};function s(o,e,p,l,u,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="自动配平讲解-脚本" aria-hidden="true"></span><h1 id="automatic-production-balancing-explanation-script" tabindex="-1">Automatic Production Balancing Explanation: Script <a class="header-anchor" href="#automatic-production-balancing-explanation-script" aria-label="Permalink to &quot;Automatic Production Balancing Explanation: Script&quot;">​</a></h1><blockquote><p>Source page ID: <code>QRCRN4XRWoQFThOwgWYo8s</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=QRCRN4XRWoQFThOwgWYo8s" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span id="source-block-2KKr78xHxC7f1BDqfS0Dba"></span></p><span class="logistics-source-anchor" id="脚本草稿02-2026-09-20-23-26" aria-hidden="true"></span><h2 id="script-draft-02-2026-09-20-23-26" tabindex="-1">Script Draft 02 (2026.09.20 23:26) <a class="header-anchor" href="#script-draft-02-2026-09-20-23-26" aria-label="Permalink to &quot;Script Draft 02 (2026.09.20 23:26)&quot;">​</a></h2><p><span id="source-block-8qmv14OgPWXRyiCEgpYUHs"></span></p><span class="logistics-source-anchor" id="_0-为什么要自动配平" aria-hidden="true"></span><h3 id="_0-why-automatic-production-balancing" tabindex="-1">0. Why Automatic Production Balancing? <a class="header-anchor" href="#_0-why-automatic-production-balancing" aria-label="Permalink to &quot;0. Why Automatic Production Balancing?&quot;">​</a></h3><p>At the beginning of version 1.4, gas industry brought two great lords:</p><p><strong>&lt;<strong><strong>（°<strong><strong>0</strong></strong>°）</strong></strong>&gt;<strong><strong>Lord Pyrrolite</strong></strong> and <strong><strong>Lord Heavy Xiranite</strong></strong>*</strong><em>（°<strong><strong>0</strong></strong>°）</em>***/**</p><p>My goodness, Lord Pyrrolite sells for 70! Its extraordinarily complicated processing is mind-blowing!</p><p>[Visual: a mysterious passage of long, difficult sentences demonstrating the complexity of Pyrrolite processing]</p><p>After all sorts of video creators worked their mathematical magic,</p><p>we now know maximum production capacity means making lots of Lord Pyrrolite and Lord Heavy Xiranite, plus two dignitaries from the previous dynasty, Lord SC Wuling Battery and Yazhen Syringe [C]—er, the lowly servant.</p><p>Ideally, no Cuprium or Xiranite remains, nor any Originium Ore or Ferrium.</p><p>Creators first proposed a balanced combination of 14.4 Pyrrolite and 24 Heavy Xiranite, then the more extreme 14.2 Pyrrolite and 26 Heavy Xiranite, very, very close to the theoretical solution!</p><p>Uh, but I am an ordinary player. Rather than squeeze production, I want to ask:</p><p><strong>What if all the inputs are balanced away and nothing is left for the Yazhen Syringe [A] I need myself? What if my mines are not all unlocked and cannot supply the line? What if I do not want to connect a Purification Node—someone else can lay that blasted conduit—but maximum production requires it? My Valley is not maxed out; there is no over-capacity transfer</strong>**...**** (Consider giving this its own screen.)**</p><p>Hey, an ordinary player with all these demands? Why not use a lower-output line consuming fewer inputs?</p><p>So what? I want high capacity and all these requirements satisfied. Is that not allowed?</p><p><strong>And so, through our efforts, automatically balanced production lines were born.</strong></p><p><span id="source-block-pvIYZjICfhBGcTSh10s5Ps"></span></p><span class="logistics-source-anchor" id="_1-局部自动配平" aria-hidden="true"></span><h3 id="_1-local-automatic-balancing" tabindex="-1">1. Local Automatic Balancing <a class="header-anchor" href="#_1-local-automatic-balancing" aria-label="Permalink to &quot;1. Local Automatic Balancing&quot;">​</a></h3><p>Understanding four inputs automatically balanced into four products right away is too difficult. First make only Pyrrolite and Heavy Xiranite.</p><p>[Visual: first show the complicated Pyrrolite Part and Heavy Xiranite recipes]</p><p>Although their recipes are complicated, do not be intimidated: ultimately they use the same two inputs, <strong>Cuprium</strong> and <strong>Xiranite</strong>.</p><p>Ignore the twists and turns in between.</p><p>[Animation: fade out complex recipes, leaving “Cuprium + Xiranite → Pyrrolite / Cuprium + Xiranite → Heavy Xiranite”]</p><p>Imagine an account like this:</p><p>l Cuprium output 360/min;</p><p>l Xiranite and Xiragen output maxed out;</p><p>Making only Pyrrolite and Heavy Xiranite, output looks like this:</p><p>[Visual: a bar chart showing their balance at the current Cuprium and Xiranite supplies]</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-50f1baa97b97076c.q90-e3e0095cf658effd.webp" alt="Automatic Production Balancing Explanation: Script"></p><p>Illustrative bar chart</p><p>Connect the remaining mines: Cuprium output rises to 510/min.</p><p>[Animation: outline extra Cuprium with a dashed box]</p><p>How do we consume the extra Cuprium? If we increase Heavy Xiranite output,</p><p>[Animation: highlight Heavy Xiranite; raise its bar and lower Pyrrolite. Xiranite stays completely occupied; Cuprium naturally decreases]</p><p>Wait, why does Cuprium consumption fall?! What if we increase the Pyrrolite bar&#39;s output?</p><p>[Animation: highlight Pyrrolite; raise it and lower Heavy Xiranite. Xiranite stays completely occupied; Cuprium increases until filling the dashed extra-Cuprium area]</p><p>Yes! All extra Cuprium is now consumed.</p><p><strong>Thus, to balance the extra <strong><strong>Cuprium</strong></strong>, <strong><strong>Pyrrolite</strong></strong> output must rise and <strong><strong>Heavy Xiranite</strong></strong> fall accordingly. (Consider giving this its own screen.)</strong></p><p>[Animation: highlight the original lengths of both product bars in lighter colors for comparison, timed to “Pyrrolite output must rise” and “Heavy Xiranite falls accordingly”]</p><p>Automatic balancing requires the line to increase Pyrrolite and decrease Heavy Xiranite spontaneously as Cuprium increases.</p><p>How? The conclusion first:</p><p>[Consider giving these two sentences their own screen] [Or an animation showing this feeding order]</p><p>l <strong>Xiranite</strong>**: satisfy the <strong><strong>Pyrrolite</strong></strong> line first, then give the remainder to <strong><strong>Heavy Xiranite</strong></strong>.**</p><p>l <strong>Cuprium</strong>**: satisfy the <strong><strong>Heavy Xiranite</strong></strong> line first, then give the remainder to <strong><strong>Pyrrolite</strong></strong>.**</p><p><span id="source-block-XIhLHRUr6EhfcCK6iuhVYV"></span></p><span class="logistics-source-anchor" id="_2-供料顺序不能反" aria-hidden="true"></span><h3 id="_2-the-feeding-order-cannot-be-reversed" tabindex="-1">2. The Feeding Order Cannot Be Reversed <a class="header-anchor" href="#_2-the-feeding-order-cannot-be-reversed" aria-label="Permalink to &quot;2. The Feeding Order Cannot Be Reversed&quot;">​</a></h3><p>Why must “Xiranite satisfy the Pyrrolite line first, and Cuprium the Heavy Xiranite line first”? Consider each separately.</p><p><span id="source-block-tQQMuKNBqugHAjmN2qGnSo"></span></p><span class="logistics-source-anchor" id="如果灼铜产线的息壤不够" aria-hidden="true"></span><h4 id="if-the-pyrrolite-line-lacks-xiranite" tabindex="-1">If the Pyrrolite Line Lacks Xiranite <a class="header-anchor" href="#if-the-pyrrolite-line-lacks-xiranite" aria-label="Permalink to &quot;If the Pyrrolite Line Lacks Xiranite&quot;">​</a></h4><p>Return to the preceding example, just after connecting the mines:</p><p>[Visual: chart with extra Cuprium outlined by a dashed box]</p><p>Try increasing Pyrrolite output: insufficient Xiranite makes it stall halfway!</p><p>[Animation: highlight Pyrrolite, raise it and lower Heavy Xiranite; Xiranite remains fully occupied. Cuprium rises but stops halfway. Flash the Pyrrolite portion of the Xiranite bar red to show insufficient supply]</p><p>Not all extra Cuprium is consumed.</p><p>[Animation: Cuprium does not fill the dashed area; flash the remaining area red to indicate unused inputs]</p><p><strong>Thus, to use the extra <strong><strong>Cuprium</strong></strong>, first satisfy the <strong><strong>Pyrrolite</strong></strong> line with <strong><strong>Xiranite</strong></strong>, ensuring enough <strong><strong>Xiranite</strong></strong>.</strong></p><p><span id="source-block-9ATxbR2VOvoPksN58XlPxb"></span></p><span class="logistics-source-anchor" id="如果重息壤产线的铜不够" aria-hidden="true"></span><h4 id="if-the-heavy-xiranite-line-lacks-cuprium" tabindex="-1">If the Heavy Xiranite Line Lacks Cuprium <a class="header-anchor" href="#if-the-heavy-xiranite-line-lacks-cuprium" aria-label="Permalink to &quot;If the Heavy Xiranite Line Lacks Cuprium&quot;">​</a></h4><p>Similarly, increase Xiranite and try to increase Heavy Xiranite output.</p><p>[Animation: highlight Heavy Xiranite, raise it and lower Pyrrolite; Cuprium stays fully occupied. Xiranite rises but stops halfway. Flash the Heavy Xiranite portion of the Cuprium bar red for insufficient supply]</p><p>Likewise, insufficient Cuprium for Heavy Xiranite leaves some extra Xiranite unused.</p><p>[Animation: flash the remaining dashed Xiranite area red to show unused inputs]</p><p>As with Pyrrolite lacking Xiranite, using the extra Xiranite requires first satisfying the Heavy Xiranite line with Cuprium.</p><p>[Visual: the preceding section&#39;s conclusion, <a href="/endfield-skydoc/explanation-automatically-balanced-production-lines-and-adaptive-devices">Explanation: Automatically Balanced Production Lines and Adaptive Devices</a>]</p><p>We have answered why Xiranite must satisfy Pyrrolite first and Cuprium satisfy Heavy Xiranite first. But another part remains: “remaining Xiranite goes to Heavy Xiranite; remaining Cuprium goes to Pyrrolite.”</p><p>[Visual: only the Heavy Xiranite bar, with unused Cuprium shown as a dashed box]</p><p>If we make only Heavy Xiranite, its line cannot use this much Cuprium.</p><p>[Animation: highlight unused dashed Cuprium area]</p><p>The Pyrrolite line must consume that remaining Cuprium.</p><p>[Animation: a Pyrrolite bar appears and grows until Cuprium is filled]</p><p>Because every input must be fully used, a line must consume the remainder. For convenience, a line specifically consuming “a particular input left by other lines” is called a:</p><p><strong>terminal</strong>** **<strong>production line (<strong>consider giving this its own screen</strong>)</strong></p><p>The Pyrrolite <span class="mark-red">line</span> is therefore the terminal line for Cuprium: the Pyrrolite <span class="mark-red">line</span> is the last line among those consuming Cuprium.</p><p>[Visual: only the Pyrrolite bar; unused Xiranite remains a dashed box]</p><p>Likewise, the Heavy Xiranite line consumes Xiranite left when making only Pyrrolite; the Heavy Xiranite <span class="mark-green">line</span> is the terminal for Xiranite.</p><p>[Animation: a Heavy Xiranite bar appears and grows until Xiranite is filled]</p><p><span id="source-block-ZVMvrKFTTnxlFhVth15pB6"></span></p><span class="logistics-source-anchor" id="_3-更多原料" aria-hidden="true"></span><h3 id="_3-more-inputs" tabindex="-1">3. More Inputs!? <a class="header-anchor" href="#_3-more-inputs" aria-label="Permalink to &quot;3. More Inputs!?&quot;">​</a></h3><p>[Visual: original Cuprium/Xiranite chart, adding Originium Ore and Ferrium to the axes]</p><p>We have handled two inputs, <span class="mark-green"></span>Cuprium<span class="mark-red"></span>Xiranite<span class="mark-green"></span>, and two products, Pyrrolite<span class="mark-red"></span>Heavy Xiranite.</p><p>Version 1.5 has two more inputs, Originium Ore and Ferrium, and two more products, <span class="mark-blue"></span>SC batteries<span class="mark-blue"></span>small medicine. (Small labels: Yazhen Syringe [C] above small medicine; SC Wuling Battery above SC batteries.)</p><p>Now add them:</p><p>[Animation: expand “Cuprium, Xiranite → Pyrrolite, Heavy Xiranite” into “Cuprium, Xiranite, Originium Ore, Ferrium → Pyrrolite, Heavy Xiranite, SC batteries, syringes”]</p><p>Dizzy? Do not rush. Our aim is to consume every input, so each input needs a line to consume what others leave. <strong>We can assign one terminal to each input!</strong></p><p>Attentive viewers may notice we sometimes use specific colors for inputs/products. Matching colors identify an input and its terminal:</p><p>Cuprium<span class="mark-red">–</span>Pyrrolite<span class="mark-red"></span>Xiranite<span class="mark-green">–</span>Heavy Xiranite<span class="mark-green"></span>Originium Ore<span class="mark-orange">–</span>SC batteries<span class="mark-orange"></span>Ferrium<span class="mark-blue">–</span>syringes</p><p>We know the Cuprium-intensive Pyrrolite <span class="mark-red">line</span> is the terminal for <span class="mark-red">input</span> Cuprium, and the Xiranite-intensive Heavy Xiranite <span class="mark-green">line</span> is the terminal for <span class="mark-green">input</span> Xiranite.</p><p>Thus, the Originium-intensive battery <span class="mark-orange">line</span> is the terminal for <span class="mark-orange">input</span> Originium Ore, and the Ferrium-intensive syringe <span class="mark-blue">line</span> is the terminal for <span class="mark-blue">input</span> Ferrium!</p><p>[Visual: highlight battery and syringe bars in sequence]</p><p>As with Pyrrolite and Heavy Xiranite, for batteries to consume all Originium Ore and syringes all Ferrium, fully supply the battery line&#39;s inputs other than Originium Ore: its Xiranite and Ferrium receive priority.</p><p>[Animation: highlight battery portions of Xiranite/Ferrium bars]</p><p>Syringes use only Ferrium, so have nothing else needing full supply.</p><p>Organize this as a table:</p><table tabindex="0"><thead><tr><th>Input</th><th>Satisfy first</th><th>Give remainder to</th><th>Terminal</th></tr></thead><tbody><tr><td>Cuprium</td><td>Heavy Xiranite</td><td>Pyrrolite</td><td>Pyrrolite</td></tr><tr><td>Xiranite</td><td>Pyrrolite<span class="mark-red"></span>SC batteries</td><td>Heavy Xiranite</td><td>Heavy Xiranite</td></tr><tr><td>Originium Ore</td><td>None</td><td>SC batteries</td><td>SC batteries</td></tr><tr><td>Ferrium</td><td>SC batteries</td><td>syringes</td><td>syringes</td></tr></tbody></table><p><span id="source-block-NscCbApRtoy9sVNgi33oLq"></span></p><span class="logistics-source-anchor" id="_4-小结" aria-hidden="true"></span><h3 id="_4-recap" tabindex="-1">4. Recap <a class="header-anchor" href="#_4-recap" aria-label="Permalink to &quot;4. Recap&quot;">​</a></h3><p>[Visual: Cuprium, Xiranite, Originium Ore, Ferrium → Pyrrolite, Heavy Xiranite, SC batteries, syringes]</p><p>For automatic balancing, grasp three things:</p><p>1.     <strong>Each input has one terminal, as <strong><strong>Cuprium</strong></strong> and <strong><strong>Xiranite</strong></strong> correspond to <strong><strong>Pyrrolite</strong></strong> and <strong><strong>Heavy Xiranite</strong></strong>.</strong></p><p>2.     <strong>Each input satisfies other lines first; the remainder goes to its terminal. For example, <strong><strong>Cuprium</strong></strong> satisfies the <strong><strong>Heavy Xiranite</strong></strong> line first, then remaining <strong><strong>Cuprium</strong></strong> goes to the <strong><strong>Pyrrolite</strong></strong> line, its <strong><strong>Cuprium</strong></strong> terminal.</strong></p><p>3.     <strong>A terminal need not be one product; it can combine several.</strong></p><p>These are the iron rules. Next implement this logic in actual lines.</p><p><span id="source-block-6W5AO6R3njsx20liAMEAHF"></span></p><span class="logistics-source-anchor" id="_5-更多样的末端" aria-hidden="true"></span><h3 id="_5-more-varied-terminals" tabindex="-1">5. More Varied Terminals <a class="header-anchor" href="#_5-more-varied-terminals" aria-label="Permalink to &quot;5. More Varied Terminals&quot;">​</a></h3><p>[Visual: 1.5 automatic maximum-gross-output example]</p><p>Must a terminal be one product? Of course not!</p><p>In the 1.5 automatic maximum-gross-output setup, before Hetonite storage fills, Hetonite/Pyrrolite output stays at 1:2. The Cuprium terminal is not simply Pyrrolite, but:</p><p><strong>Hetonite</strong>** and <strong><strong>Pyrrolite</strong></strong> at 1:2.**</p><p>[Animation: Cuprium flows to a combined “Hetonite + Pyrrolite” icon]</p><p>Regard a combined terminal as the product of a custom recipe, just like the earlier single-product terminals.</p><p><span id="source-block-alfvXe1QvMYfZj3cfhrjDu"></span></p><span class="logistics-source-anchor" id="_6-回到实际的产线中去" aria-hidden="true"></span><h3 id="_6-back-to-actual-production-lines" tabindex="-1">6. Back to Actual Production Lines <a class="header-anchor" href="#_6-back-to-actual-production-lines" aria-label="Permalink to &quot;6. Back to Actual Production Lines&quot;">​</a></h3><p>Return to the strongest AIC (automatic maximum gross output) and identify priority-supplied lines:</p><p>l Pyrrolite is not Xiranite&#39;s terminal, so its Xiranite receives priority. [Show Liquid Xiranite oversupply for Pyrrolite and Xiranite oversupply for Separator Cores]</p><p>l Heavy Xiranite is not Cuprium&#39;s terminal, so its Cuprium receives priority. [Show Cuprium oversupply for Separator Cores]</p><p>l Batteries are neither Xiranite&#39;s nor Ferrium&#39;s terminal, so their Xiranite and Ferrium receive priority. [Show Xiranite oversupply for batteries and Ferrium oversupply for Ferrium shredding]</p><p>l Syringes have no other input besides Ferrium, so they are only its terminal, with nothing to satisfy first.</p><p>Do not limit yourself to adding Depot Unloaders for priority supply! There are many ways:</p><p>Direct overflow from the Forge of the Sky to prioritize Xiranite; full-storage oscillation; oversupply one belt and use its overflow; and approaches we have not covered...</p><p><span id="source-block-nMGg9n9gbR14AeQnIFzEEs"></span></p><span class="logistics-source-anchor" id="_7-为什么支持自行添加产线" aria-hidden="true"></span><h3 id="_7-why-can-you-add-your-own-lines" tabindex="-1">7. Why Can You Add Your Own Lines? <a class="header-anchor" href="#_7-why-can-you-add-your-own-lines" aria-label="Permalink to &quot;7. Why Can You Add Your Own Lines?&quot;">​</a></h3><p>Finish with something simple and relax.</p><p>Remember the “ordinary-player requirements” at the beginning? [Show the corresponding clip]</p><p>Most of our explanation concerns how the balancing line balances itself. If you add a new line manually, how does it handle that line&#39;s consumption?</p><p>Treat inputs consumed by your own line as never entering the balancing system, like an unopened mine. After removing that portion, the balancing line converts every remaining input into the products we want.</p><p><strong>Thus our extravagant wish to have everything comes true.</strong></p><p>One final question: how far can you add lines—or at what input ratios can the balancing line no longer balance all remaining inputs? (Wait 10s, then play ending.)</p><p>Ending:</p><p>That concludes the automatic-balancing/adaptive production-line explanation.</p><p>See you next time for “Adaptive Devices”!</p><p>[Visual: members&#39; signatures] (to be discussed)</p></div>',1)])])}const g=i(n,[["render",s]]);export{h as __pageData,g as default};
